fn solve(input: Vec<char>) -> Vec<char> {
    // A helper that maps a digit character to its "good count".
    fn good_count(d: char) -> u32 {
        match d {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // input is guaranteed to be digits for first two chars
        }
    }

    // Take only the first two characters of the input
    let d1 = input[0];
    let d2 = input[1];

    // Compute the product of their good counts
    let product = good_count(d1) * good_count(d2);

    // Convert the product to its decimal representation and collect into chars
    let mut output: Vec<char> = product.to_string().chars().collect();

    // Append the mandatory trailing newline
    output.push('\n');
    output
}